define("tool_disclaimer/admin_withdraw_user",["exports","core/ajax","core/modal_save_cancel","core/modal_events","core/notification","core/str"],function(_exports,Ajax,ModalSaveCancel,ModalEvents,Notification,Str){
    "use strict";
    Object.defineProperty(_exports, "__esModule", {value: true});
    _exports.init = void 0;
    Ajax = Ajax.default || Ajax;
    ModalSaveCancel = ModalSaveCancel.default || ModalSaveCancel;
    ModalEvents = ModalEvents.default || ModalEvents;
    Notification = Notification.default || Notification;
    let currentUser = null;
    const loadUser = async(userid) => {
        try {
            const data = await Ajax.call([{
                methodname: 'tool_disclaimer_manage_get_withdraw_status',
                args: {userid: userid}
            }])[0];
            currentUser = data;
            await renderUserPanel(data);
        } catch (error) {
            Notification.exception(error);
        }
    };
    const renderUserPanel = async(data) => {
        const panel = document.getElementById('tool-disclaimer-admin-user-panel');
        const infoEl = document.getElementById('tool-disclaimer-admin-user-info');
        const listEl = document.getElementById('tool-disclaimer-admin-disclaimer-list');
        const withdrawBtn = document.getElementById('tool-disclaimer-admin-withdraw-btn');
        infoEl.textContent = `${data.fullname} (${data.email}) - ID: ${data.userid}`;
        if (data.disclaimers.length === 0) {
            const noneStr = await Str.getString('admin_withdraw_none', 'tool_disclaimer');
            listEl.innerHTML = `<p class="text-muted mb-0">${noneStr}</p>`;
            withdrawBtn.classList.add('d-none');
        } else {
            const selectAllLabel = await Str.getString('withdraw_select_all_disclaimers', 'tool_disclaimer');
            let html = `<div class="form-check mb-2"><input id="tool-disclaimer-admin-all" class="form-check-input" type="checkbox"><label for="tool-disclaimer-admin-all" class="form-check-label fw-semibold">${selectAllLabel}</label></div><div class="border rounded p-2" style="max-height:300px;overflow-y:auto;">`;
            data.disclaimers.forEach((d) => {
                html += `<div class="form-check"><input id="tool-disclaimer-admin-item-${d.id}" class="form-check-input tool-disclaimer-admin-item" type="checkbox" value="${d.id}"><label for="tool-disclaimer-admin-item-${d.id}" class="form-check-label">${d.name} <span class="text-muted">(${d.context})</span></label></div>`;
            });
            html += '</div>';
            listEl.innerHTML = html;
            withdrawBtn.classList.add('d-none');
        }
        panel.classList.remove('d-none');
    };
    const toggleWithdrawButton = () => {
        const withdrawBtn = document.getElementById('tool-disclaimer-admin-withdraw-btn');
        const allChecked = !!(document.getElementById('tool-disclaimer-admin-all') || {}).checked;
        const anyItemChecked = document.querySelectorAll('.tool-disclaimer-admin-item:checked').length > 0;
        if (allChecked || anyItemChecked) {
            withdrawBtn.classList.remove('d-none');
        } else {
            withdrawBtn.classList.add('d-none');
        }
    };
    const handleWithdraw = async() => {
        if (!currentUser) {
            return;
        }
        const withdrawall = !!(document.getElementById('tool-disclaimer-admin-all') || {}).checked;
        const selected = Array.from(document.querySelectorAll('.tool-disclaimer-admin-item:checked'))
            .map((cb) => parseInt(cb.value, 10))
            .filter((id) => id > 0);
        if (!withdrawall && selected.length === 0) {
            Notification.addNotification({
                type: 'warning',
                message: await Str.getString('withdraw_select_one', 'tool_disclaimer')
            });
            return;
        }
        const [title, message, button] = await Promise.all([
            Str.getString('withdraw_confirm_title', 'tool_disclaimer'),
            Str.getString('admin_withdraw_confirm_message', 'tool_disclaimer', currentUser.fullname),
            Str.getString('withdraw_now', 'tool_disclaimer')
        ]);
        const confirmModal = await ModalSaveCancel.create({title: title, body: message, removeOnClose: true});
        confirmModal.setSaveButtonText(button);
        confirmModal.getRoot().on(ModalEvents.save, async() => {
            try {
                const result = await Ajax.call([{
                    methodname: 'tool_disclaimer_manage_withdraw',
                    args: {
                        userid: currentUser.userid,
                        disclaimerids: selected,
                        withdrawall: withdrawall
                    }
                }])[0];
                confirmModal.destroy();
                Notification.addNotification({
                    type: result.success ? 'success' : 'warning',
                    message: result.message
                });
                if (result.success) {
                    await loadUser(currentUser.userid);
                }
            } catch (error) {
                Notification.exception(error);
            }
        });
        confirmModal.getRoot().on(ModalEvents.hidden, () => confirmModal.destroy());
        confirmModal.show();
    };
    const init = (params = {}) => {
        const withdrawBtn = document.getElementById('tool-disclaimer-admin-withdraw-btn');
        if (!withdrawBtn) {
            return;
        }
        withdrawBtn.addEventListener('click', () => {
            void handleWithdraw();
        });
        document.getElementById('tool-disclaimer-admin-disclaimer-list')?.addEventListener('change', (e) => {
            if (e.target.id === 'tool-disclaimer-admin-all') {
                const checked = e.target.checked;
                document.querySelectorAll('.tool-disclaimer-admin-item').forEach((cb) => {
                    cb.checked = false;
                    cb.disabled = checked;
                });
            }
            toggleWithdrawButton();
        });
        const userid = parseInt(params.userid, 10);
        if (userid > 0) {
            void loadUser(userid);
        }
    };
    _exports.init = init;
});
